 let edges='';for(const a of map)for(const b of map)if(J.links(a,b)){const [x,y]=xy(a),[xx,yy]=xy(b),traveled=a.visited&&b.visited,nextStep=a.id===state.nodeId&&available.some(n=>n.id===b.id),branch=descendants.has(a.id)&&descendants.has(b.id);edges+=`<path class="${traveled?'traveled':nextStep?'next-step':branch?'branch':''}" d="M${x} ${y}C${x} ${y-38} ${xx} ${yy+38} ${xx} ${yy}"/>`;}
