 if(d.node){clearTimeout(toastTimer);$('#toast').classList.remove('visible');selectedNode=d.node;const n=state.maps[state.chapter-1].find(n=>n.id===d.node);render();if(n?.visited)toast('此处已行过，仅供回看');else if(!J.available(state).some(q=>q.id===d.node))toast('此处暂不可前往，请选择标有「可前往」的地点');return;}
